const AI_SQUADS_CUSTOM_KEY = 'FANTA_MASTER_AI_SQUADS_CUSTOM_V1';
function getAiSquadsOverrides() {
    try {
        const raw = localStorage.getItem(AI_SQUADS_CUSTOM_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch (e) {
        console.warn("Errore lettura AI squads custom:", e);
        return {};
    }
}
function saveAiSquadsOverrides(overrides) {
    try {
        localStorage.setItem(AI_SQUADS_CUSTOM_KEY, JSON.stringify(overrides));
    } catch (e) {
        console.warn("Errore salvataggio AI squads custom:", e);
    }
}
function getAiSquadsData() {
    const isMantra = (typeof State !== 'undefined' && State.systemMode === 'mantra');
    const baseList = isMantra ? MANTRA_AI_SQUADS_DATA : AI_SQUADS_DATA;
    const overrides = getAiSquadsOverrides();
    return baseList.map(baseSq => {
        const sq = JSON.parse(JSON.stringify(baseSq));
        sq.originalStarters = JSON.parse(JSON.stringify(baseSq.starters));
        sq.originalBench = JSON.parse(JSON.stringify(baseSq.bench));
        sq.isCustomized = false;
        const ov = overrides[sq.id];
        if (ov) {
            ['P', 'D', 'C', 'A'].forEach(r => {
                if (ov.starters && Array.isArray(ov.starters[r])) {
                    ov.starters[r].forEach((customName, idx) => {
                        if (customName && sq.starters[r] && idx < sq.starters[r].length) {
                            sq.starters[r][idx] = customName;
                        }
                    });
                }
                if (ov.bench && Array.isArray(ov.bench[r])) {
                    ov.bench[r].forEach((customName, idx) => {
                        if (customName && sq.bench[r] && idx < sq.bench[r].length) {
                            sq.bench[r][idx] = customName;
                        }
                    });
                }
            });
            let hasChanges = false;
            ['P', 'D', 'C', 'A'].forEach(r => {
                (sq.starters[r] || []).forEach((n, idx) => {
                    if (sq.originalStarters[r] && sq.originalStarters[r][idx] && n.toLowerCase().trim() !== sq.originalStarters[r][idx].toLowerCase().trim()) {
                        hasChanges = true;
                    }
                });
                (sq.bench[r] || []).forEach((n, idx) => {
                    if (sq.originalBench[r] && sq.originalBench[r][idx] && n.toLowerCase().trim() !== sq.originalBench[r][idx].toLowerCase().trim()) {
                        hasChanges = true;
                    }
                });
            });
            sq.isCustomized = hasChanges;
        }
        return sq;
    });
}
function replaceAiPlayer(squadId, roleKey, isStarter, slotIndex, newPlayerName) {
    const overrides = getAiSquadsOverrides();
    if (!overrides[squadId]) {
        overrides[squadId] = { starters: {}, bench: {} };
    }
    const targetGroup = isStarter ? 'starters' : 'bench';
    if (!overrides[squadId][targetGroup]) overrides[squadId][targetGroup] = {};
    if (!overrides[squadId][targetGroup][roleKey]) {
        const baseSquads = (typeof State !== 'undefined' && State.systemMode === 'mantra') ? MANTRA_AI_SQUADS_DATA : AI_SQUADS_DATA;
        const sq = baseSquads.find(s => s.id === squadId);
        overrides[squadId][targetGroup][roleKey] = sq ? [...(sq[targetGroup][roleKey] || [])] : [];
    }
    overrides[squadId][targetGroup][roleKey][slotIndex] = newPlayerName;
    saveAiSquadsOverrides(overrides);
    renderAiSquadsTab();
}
function revertAiSquadPlayer(squadId, roleKey, isStarter, slotIndex) {
    const overrides = getAiSquadsOverrides();
    if (overrides[squadId]) {
        const targetGroup = isStarter ? 'starters' : 'bench';
        const baseSquads = (typeof State !== 'undefined' && State.systemMode === 'mantra') ? MANTRA_AI_SQUADS_DATA : AI_SQUADS_DATA;
        const sq = baseSquads.find(s => s.id === squadId);
        if (sq && sq[targetGroup] && sq[targetGroup][roleKey] && overrides[squadId][targetGroup] && overrides[squadId][targetGroup][roleKey]) {
            overrides[squadId][targetGroup][roleKey][slotIndex] = sq[targetGroup][roleKey][slotIndex];
            saveAiSquadsOverrides(overrides);
            renderAiSquadsTab();
        }
    }
}
function resetAiSquadToDefault(squadId) {
    const overrides = getAiSquadsOverrides();
    if (overrides[squadId]) {
        if (!confirm("Vuoi ripristinare tutti i 25 calciatori della formazione al modello originale consigliato dall'AI?")) {
            return;
        }
        delete overrides[squadId];
        saveAiSquadsOverrides(overrides);
        renderAiSquadsTab();
    }
}
